public sealed class LyricLine {public double Time;public string Text;}
public static class Lyrics {
 public static List<LyricLine> Parse(string text){
  var lines=new List<LyricLine>();var off=Regex.Match(text??"",@"\[offset:([+-]?\d+)\]",RegexOptions.IgnoreCase);double offset=off.Success?double.Parse(off.Groups[1].Value,CultureInfo.InvariantCulture)/1000:0;
  foreach(var row in (text??"").Split('\n')){var matches=Regex.Matches(row,@"\[(\d+):(\d{1,2})(?:[.:](\d{1,3}))?\]");if(matches.Count==0)continue;var content=Regex.Replace(row,@"\[[^\]]*\]","").Trim();foreach(Match m in matches){double fraction=m.Groups[3].Success?double.Parse("0."+m.Groups[3].Value,CultureInfo.InvariantCulture):0;lines.Add(new LyricLine{Time=int.Parse(m.Groups[1].Value)*60+int.Parse(m.Groups[2].Value)+fraction+offset,Text=content});}}
  return lines.OrderBy(x=>x.Time).ToList();
 }
 public static int Index(List<LyricLine> lines,double position){int lo=0,hi=lines.Count-1,found=-1;while(lo<=hi){int mid=(lo+hi)/2;if(lines[mid].Time<=position){found=mid;lo=mid+1;}else hi=mid-1;}return found;}
}
